"""Pages de transparence fondées sur le fonctionnement réel du site statique."""
from pathlib import Path
from html import escape
from urllib.parse import urlparse
import json,hashlib,base64,re

ROOT=Path(__file__).resolve().parent
CSP="default-src 'none'; script-src 'self'; style-src 'self' 'unsafe-inline'; connect-src 'self'; img-src 'self' data:; font-src 'self'; object-src 'none'; base-uri 'none'; form-action 'none'; upgrade-insecure-requests"

def esc(value):return escape(str(value),quote=True)
def config():return json.loads((ROOT/'site-config.json').read_text(encoding='utf-8'))
def link(url,label):
 if urlparse(url).scheme!='https':raise ValueError('Lien public non HTTPS')
 return '<a href="'+esc(url)+'" target="_blank" rel="noopener noreferrer">'+esc(label)+'</a>'
def head_security():return '<meta http-equiv="Content-Security-Policy" content="'+esc(CSP)+'"><meta name="referrer" content="no-referrer">'
def footer(c):
 return '<div class="legal-footer"><p>© 2026 '+esc(c['publisherName'])+' · '+esc(c['siteName'])+'. Droits sur les créations originales réservés ; les données et documents tiers conservent leurs propres droits.</p><nav aria-label="Informations du site"><a href="mentions-legales.html">Mentions légales</a> · <a href="confidentialite.html">Confidentialité</a> · <a href="conditions-utilisation.html">Conditions d’utilisation</a> · <a href="securite.html">Sécurité et contact</a></nav><p>Édité par '+esc(c['publisherName'])+' · '+link(c['repository'],'Dépôt officiel et historique du projet')+'</p></div>'
def page(c,title,body,name):
 return '<!doctype html><html lang="fr"><head><meta charset="utf-8">'+head_security()+'<meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(title+' · '+c['publicTitle'])+'</title><link rel="canonical" href="'+esc(c['canonicalUrl']+name)+'"><link rel="stylesheet" href="style.css"></head><body><header><a class="brand" href="index.html">◈ '+esc(c['siteName'])+'</a><a href="index.html">Retour aux analyses</a></header><main class="information-page"><p class="eyebrow">PAR '+esc(c['publisherName']).upper()+'</p><h1>'+esc(title)+'</h1><p>Version du '+esc(c['legalUpdated'])+'.</p>'+body+footer(c)+'</main></body></html>'
def generate(out):
 c=config();publisher=esc(c['publisherName']);public=link(c['publicContactUrl'],'espace de contact public du projet')
 private=('<a href="mailto:'+esc(c['privateContactEmail'])+'">'+esc(c['privateContactEmail'])+'</a>') if c.get('privateContactEmail') else 'Aucune adresse de contact privée n’est encore publiée. N’envoyez aucune donnée personnelle dans l’espace public du projet.'
 owner_note='<p>Identité juridique : '+esc(c.get('legalIdentity') or 'À compléter')+'. Pays d’établissement : '+esc(c.get('country') or 'À compléter')+'.</p>'
 if not (c.get('legalIdentity') and c.get('country') and c.get('privateContactEmail')):owner_note+='<p class="notice">L’éditeur utilise actuellement un nom public. Son identité juridique complète, son pays d’établissement et ses coordonnées privées restent à compléter avant une exploitation professionnelle. Cette page ne vaut pas certification de conformité à une juridiction déterminée.</p>'
 mentions=f'''<h2>Éditeur et attribution</h2><p>Le site {esc(c['siteName'])} est édité sous le nom public <strong>{publisher}</strong>. Le dépôt officiel est administré sous le compte GitHub {esc(c['ownerAccount'])} : {link(c['repository'],'consulter le dépôt et les dates des modifications')}.</p>{owner_note}
 <h2>Hébergement</h2><p>Ce site statique est hébergé sur GitHub Pages, service de GitHub. Les informations et coordonnées actualisées de l’hébergeur sont disponibles dans {link('https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement','la politique GitHub et ses moyens de contact')}.</p>
 <h2>Créations originales et sources tierces</h2><p>La présentation, le code et les contenus originaux du projet sont réservés à leurs titulaires dans la mesure où ils sont protégeables. Aucune licence générale de réutilisation n’est accordée. Les exceptions légales et les droits de consultation et de fork prévus par les conditions de GitHub restent applicables. La disponibilité publique du code n’est pas une cession de propriété.</p><p>Les données de marché, les rapports et les marques de la BRVM, des émetteurs et des autres sources appartiennent à leurs titulaires respectifs. Leur présence ne confère pas à l’éditeur de droits exclusifs sur ces éléments. Un lien ou un téléchargement public n’accorde pas automatiquement un droit de redistribution commerciale.</p>
 <h2>Indépendance</h2><p>Le site n’est ni un service officiel de la BRVM ni une plateforme de SGI. Il ne transmet aucun ordre, ne reçoit aucun dépôt et ne demande aucun identifiant de compte titres. Le nom public de l’éditeur ne constitue pas une déclaration d’agrément professionnel.</p><h2>Contact</h2><p>Questions générales sans données sensibles : {public}. Contact privé : {private}</p>'''
 privacy=f'''<h2>Fonctionnement de cette version</h2><p>Le responsable éditorial est {publisher}, identifié dans les <a href="mentions-legales.html">mentions légales</a>. Cette version ne propose ni compte utilisateur, ni paiement, ni formulaire de collecte, ni publicité, ni outil de mesure d’audience ajouté par l’éditeur.</p>
 <h2>Vos choix et simulations</h2><p>Les filtres, comparaisons, montants de simulation et paramètres saisis sont traités dans la mémoire de l’onglet. Le site public ne les envoie pas à un serveur de l’éditeur et ne les enregistre pas dans des cookies, localStorage ou sessionStorage. Ils disparaissent à la fermeture ou au rechargement de l’onglet. Un export CSV reste sur l’appareil où vous le téléchargez ; sa conservation dépend de vous.</p>
 <h2>Connexion à l’hébergeur</h2><p>Afficher les pages et vérifier leur actualisation implique des requêtes vers GitHub Pages. L’hébergeur peut traiter notamment l’adresse IP et des informations techniques de connexion pour délivrer et sécuriser son service. Les finalités, bases juridiques, destinataires, durées ou critères de conservation, transferts internationaux et modalités d’exercice des droits relevant de GitHub sont décrits dans {link('https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement','sa politique de confidentialité')}. L’éditeur ne reçoit pas, dans cette application, de tableau de suivi individuel des visiteurs.</p>
 <h2>Cookies et suivi</h2><p>Le code de cette version ne dépose ni cookie de suivi ni identifiant publicitaire et n’intègre aucun contenu distant dans la page. Aucun consentement publicitaire n’est sollicité puisqu’aucun tel outil n’est activé. Toute introduction ultérieure d’un outil soumis au consentement nécessitera une information et un choix préalables adaptés.</p>
 <h2>Sources et liens externes</h2><p>La collecte des données boursières est effectuée séparément sur GitHub Actions. Votre navigateur reçoit la copie publiée sur ce site. Ouvrir volontairement un lien externe vous conduit vers un autre service, soumis à ses propres pratiques de confidentialité. Les publications peuvent citer des dirigeants ou représentants dans le cadre de leur activité publique ; une erreur de rattachement ou une information à rectifier peut être signalée.</p>
 <h2>Contact et droits</h2><p>Contact privé de l’éditeur : {private} Pour les données traitées par GitHub, utilisez les moyens indiqués dans sa politique. Selon la législation applicable, des droits d’accès, rectification, effacement, limitation ou opposition peuvent s’exercer, ainsi qu’un recours auprès de l’autorité compétente. Ne publiez ni document d’identité, ni identifiant financier, ni information confidentielle dans {public}.</p><p>Si vous ouvrez une demande publique sur GitHub, son contenu et votre compte peuvent être visibles par tous ; ce traitement relève aussi des conditions et de la politique de GitHub.</p>'''
 terms='''<h2>Objet du service</h2><p>BRVM Conseil est un outil d’information et d’analyse générale. Les données de marché et les estimations sont accompagnées de leur date, de leurs sources et de leurs limites. Les prix affichés peuvent être différés ou provenir du dernier bulletin disponible.</p><h2>Estimations et décisions</h2><p>Une probabilité, un score ou une fourchette n’est pas une garantie de mouvement, d’exécution ou de rendement. Les prévisions peuvent être erronées. Les informations ne constituent pas un conseil personnalisé et ne remplacent pas l’examen de votre situation avec un professionnel habilité.</p><h2>Disponibilité et actualisation</h2><p>Les collectes sont programmées automatiquement. Une panne de source, un changement de format, une fermeture de marché ou un retard de l’hébergeur peut différer une publication. Les dernières données valides sont conservées lorsque cela est possible. Une donnée ancienne n’est pas présentée comme une nouvelle séance.</p><h2>Utilisation des contenus</h2><p>Respectez les droits des créateurs et des sources tierces. Ne présentez pas une copie comme le site officiel de l’éditeur. Les exceptions légales et les autorisations expressément accordées restent applicables. Aucune marque n’est présentée comme déposée par le seul affichage de ces mentions.</p><h2>Responsabilités et évolution</h2><p>Aucune promesse de gain ou de disponibilité permanente n’est faite. Ces conditions ne suppriment aucune obligation légale ni aucun droit impératif applicable. Le service et ces informations peuvent évoluer ; la date de version permet de repérer les changements.</p>'''
 security=f'''<h2>Identifier le site officiel</h2><p>L’adresse officielle est {link(c['canonicalUrl'],c['canonicalUrl'])}. Son responsable public est {publisher}. Vérifiez le domaine avant d’utiliser une copie ou de suivre un lien reçu par message.</p><h2>Ce que le site ne vous demandera pas</h2><p>Aucun mot de passe de SGI, code de validation, clé d’accès, transfert d’argent ou document d’identité n’est nécessaire pour consulter les analyses. Aucune opération financière n’est exécutée depuis ce site.</p><h2>Signaler un problème</h2><p>Pour un lien cassé ou une erreur non confidentielle : {public}. Pour une faille ou une demande contenant des données personnelles : {private} N’exposez jamais publiquement un secret, une preuve contenant des données de tiers ou un moyen d’accès à un compte.</p><h2>Protection et limites</h2><p>Le site utilise HTTPS, limite les ressources exécutées dans la page et conserve les versions de ses données et de son code. Ces mesures réduisent les risques sans garantir une protection absolue. Un changement de compte GitHub, de domaine ou de contenu ne doit pas être accepté sans vérification.</p><h2>Actualisation</h2><p>La date du dernier bulletin et l’état de la dernière collecte sont affichés sur la page d’analyse. Un message de retard ou d’indisponibilité signifie qu’il faut vérifier l’actualité des chiffres avant de les utiliser.</p>'''
 for filename,title,body in [('mentions-legales.html','Mentions légales et propriété',mentions),('confidentialite.html','Politique de confidentialité',privacy),('conditions-utilisation.html','Conditions d’utilisation',terms),('securite.html','Sécurité et contact',security)]:
  (out/filename).write_text(page(c,title,body,filename),encoding='utf-8')
 research='''<h2>Évaluation du 13 novembre 2026</h2><p>Ce contrôle ponctuel ne certifie ni un prestataire, ni ses prévisions. Les cours de clôture, les instantanés intrajournaliers, les cours de référence et les prix sans échange doivent rester distincts.</p>
 <h2>BRVM Screener</h2><p>La page marché du 12 novembre 2026 présente des clôtures correspondant à notre bulletin officiel sur les 46 actions avec échange comparées. Les deux lignes sans transaction ont été exclues de cette comparaison. Cela appuie l’utilisation comme contrôle secondaire pour cette séance ; ce résultat ne mesure ni la fiabilité de tout l’historique, ni celle des ratios ou signaux.</p><p>Le site indique utiliser les bulletins et les sources publiques. Ses conditions limitent l’extraction massive et la réutilisation. Aucune collecte systématique de ses tableaux n’est activée ici ; un export ou accès autorisé est nécessaire avant une intégration durable.</p><p><a href="https://brvmscreener.com/marche" target="_blank" rel="noopener noreferrer">Page marché examinée</a> · <a href="https://brvmscreener.com/legal" target="_blank" rel="noopener noreferrer">Conditions du fournisseur</a></p>
 <h2>BloomAfrik</h2><p>Les pages publiques présentent des outils d’analyse et une documentation, mais la lecture publique effectuée n’a pas permis de comparer une série complète de clôtures datées aux bulletins. Certaines fonctions demandent une connexion. Sa fiabilité chiffrée reste donc non évaluée ici ; cette limite d’accès ne prouve pas une mauvaise qualité.</p><p>La mention « temps réel » du tableau de bord ne constitue pas une preuve de flux seconde par seconde. La documentation décrit principalement une actualisation après clôture ; le carnet annoncé est constitué de quantités résiduelles de fin de séance. Aucun flux temps réel ni historique BloomAfrik n’est injecté dans les modèles.</p><p><a href="https://app.bloomafrik.com/" target="_blank" rel="noopener noreferrer">Tableau de bord</a> · <a href="https://app.bloomafrik.com/documentation" target="_blank" rel="noopener noreferrer">Documentation</a></p>
 <h2>Ce qui peut améliorer la prévision</h2><ol><li>Étendre les historiques officiels, corriger les fractionnements et traiter les suspensions avant d’ajouter des modèles.</li><li>Archiver les annonces et les données de fin de séance avec l’heure de leur première disponibilité. Un carnet résiduel ne remplace pas le flux d’ordres intrajournalier.</li><li>Tester chaque nouvelle variable sur les mêmes dates et contre le repère « cours inchangé », puis suivre les résultats réellement futurs par version.</li><li>Contrôler la calibration des probabilités, la couverture des fourchettes et la liquidité ; conserver un signal incertain lorsque les éléments sont insuffisants.</li></ol>
 <p>Deux sites recopiant le même bulletin ne constituent pas deux informations prédictives indépendantes. Une nouvelle source améliore surtout les contrôles ; son apport au prix prévu doit être démontré séparément. Aucune promesse d’erreur très petite n’est faite.</p>
 <h2>Actualisation à la demande</h2><p>Sur la page d’analyse, « Charger la dernière publication » recherche la version disponible. « Lancer une collecte · propriétaire » ouvre le workflow GitHub ; avec un compte autorisé, sélectionner « Run workflow ». Une collecte peut durer plusieurs minutes, puis les contrôles précèdent sa publication. Aucun identifiant GitHub ou SGI n’est demandé par le site.</p><p>Le contrôle léger des cours est programmé environ toutes les cinq minutes en journée du lundi au vendredi (9 h à 19 h UTC) ; la collecte complète reste horaire. Le service à 60 secondes est préparé, mais aucun serveur permanent n’est encore raccordé. La date du bulletin, la tentative de collecte et la date de publication sont indiquées séparément : republier une ancienne séance ne la rend pas nouvelle.</p>'''
 (out/'fiabilite-sources.html').write_text(page(c,'Fiabilité des sources et amélioration des prévisions',research,'fiabilite-sources.html'),encoding='utf-8')
 return footer(c)

def manifest(out):
 files=sorted(p for p in out.iterdir() if p.is_file() and p.name not in ('integrite-publication.json','status-public.json'))
 payload={'version':1,'files':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in files}}
 (out/'integrite-publication.json').write_text(json.dumps(payload,ensure_ascii=False,indent=2),encoding='utf-8')
 return {p.name:'sha256-'+base64.b64encode(hashlib.sha256(p.read_bytes()).digest()).decode() for p in files if p.suffix=='.js'}
